class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = "1" + s + "1"
        ones = s.count("1")
        zero_blocks = []

        i = 0
        while i < len(t):
            if t[i] == "0":
                j = i
                while j < len(t) and t[j] == "0":
                    j += 1
                zero_blocks.append(j - i)
                i = j
            else:
                i += 1

        best_gain = 0
        for i in range(len(zero_blocks) - 1):
            best_gain = max(best_gain, zero_blocks[i] + zero_blocks[i + 1])

        return ones + best_gain
